package com.example.mi_bolt_backend.demo;

import java.time.OffsetDateTime;
import java.util.UUID;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * The one demo account the demo gate signs in against (MIM-423). Its id is a UUID
 * generated by Hibernate ({@link GenerationType#UUID}); {@code passwordHash} stores
 * the output of {@code PasswordEncoderFactories.createDelegatingPasswordEncoder()}
 * ({@code {bcrypt}} prefix plus the 60-character bcrypt string), the same encoder the
 * admin accounts use. The row is created at startup by {@link DemoAccessBootstrap}
 * when the table is empty, so the username is the configured one rather than a
 * constant.
 *
 * <p>Schema lives in Liquibase changeset {@code 0010-demo-access.yaml}.
 */
@Entity
@Table(name = "demo_user")
public class DemoUser {

	@Id
	@GeneratedValue(strategy = GenerationType.UUID)
	@Column(nullable = false, updatable = false)
	private UUID id;

	@Column(nullable = false, length = 80, unique = true)
	private String username;

	@Column(name = "password_hash", nullable = false, length = 100)
	private String passwordHash;

	@Column(name = "created_at", nullable = false)
	private OffsetDateTime createdAt;

	protected DemoUser() {
		// JPA requires a no-arg constructor; field initialisation happens through the named constructor.
	}

	public DemoUser(String username, String passwordHash, OffsetDateTime createdAt) {
		this.username = username;
		this.passwordHash = passwordHash;
		this.createdAt = createdAt;
	}

	public String getUsername() {
		return username;
	}

	public String getPasswordHash() {
		return passwordHash;
	}

	public OffsetDateTime getCreatedAt() {
		return createdAt;
	}
}
